const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open);menu.setAttribute('aria-label',open?'Menü bezárása':'Menü megnyitása');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open');}});
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const subject=form.dataset.kind==='newsletter'?'Érdeklődés az Arcápolási Kisokosról':'Időpontkérés – Eliza Beauty Salon';const body=`Név: ${data.get('name')}\nE-mail: ${data.get('email')}\n\n${data.get('message')||'Szeretnék érdeklődni az Arcápolási Kisokos elérhetőségéről.'}`;location.href=`mailto:hello.elizabeauty@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;form.querySelector('.status').textContent='Az üzenet előkészítve. A küldést a levelezőalkalmazásodban fejezheted be. Ha nem nyílt meg, használd a fenti e-mail címet.';}));
document.querySelectorAll('.package .button').forEach(button=>button.addEventListener('click',()=>{const message=document.querySelector('#idopont textarea');message.value=`A következő csomag érdekel: ${button.closest('.package').querySelector('h3').textContent}. Szeretnék időpontot egyeztetni.`;}));
